import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { MapContainer, TileLayer, useMap } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import './Simulador.css';

// Fix for default markers
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

// Mock Data
const ALL_AIRPORTS = [
  { id: 1, name: 'Aeropuerto Internacional de São Paulo-Guarulhos', code: 'GRU', country: 'Brasil', region: 'Sudamérica', lat: -23.4356, lng: -46.4731, capacity: 500000, packages: 0, isSede: true, operationType: 'Hub Principal' },
  { id: 2, name: 'Aeropuerto Internacional de El Dorado', code: 'BOG', country: 'Colombia', region: 'Sudamérica', lat: 4.7016, lng: -74.1469, capacity: 300000, packages: 0, isSede: false, operationType: 'Regional Hub' },
  { id: 3, name: 'Aeropuerto Internacional de Pudahuel', code: 'SCL', country: 'Chile', region: 'Sudamérica', lat: -33.393, lng: -70.7858, capacity: 200000, packages: 0, isSede: false, operationType: 'Regional Hub' },
  { id: 4, name: 'Aeropuerto Internacional de Ciudad de México', code: 'MEX', country: 'México', region: 'Norteamérica', lat: 19.4363, lng: -99.0719, capacity: 400000, packages: 0, isSede: false, operationType: 'Hub Secundario' },
  { id: 5, name: 'Aeropuerto Internacional de Lima Jorge Chávez', code: 'LIM', country: 'Perú', region: 'Sudamérica', lat: -12.0219, lng: -77.1147, capacity: 180000, packages: 0, isSede: false, operationType: 'Centro de Distribución' },
  { id: 6, name: 'Aeropuerto Internacional de Miami', code: 'MIA', country: 'EE. UU.', region: 'Norteamérica', lat: 25.795, lng: -80.287, capacity: 600000, packages: 0, isSede: false, operationType: 'Centro de Distribución' },
];

const initialFlights = [
  {
    id: 'V-001',
    origin: ALL_AIRPORTS.find(a => a.code === 'GRU'),
    destination: ALL_AIRPORTS.find(a => a.code === 'BOG'),
    currentPackages: 10000,
    packageCapacity: 15000,
    progress: 0,
    status: 'scheduled',
    aircraftType: 'boeing737',
    aircraftColor: '#007bff',
    isSameContinentFlight: true
  },
  {
    id: 'V-002',
    origin: ALL_AIRPORTS.find(a => a.code === 'BOG'),
    destination: ALL_AIRPORTS.find(a => a.code === 'SCL'),
    currentPackages: 8000,
    packageCapacity: 12000,
    progress: 0,
    status: 'scheduled',
    aircraftType: 'airbus320',
    aircraftColor: '#28a745',
    isSameContinentFlight: true
  },
  {
    id: 'V-003',
    origin: ALL_AIRPORTS.find(a => a.code === 'GRU'),
    destination: ALL_AIRPORTS.find(a => a.code === 'MIA'),
    currentPackages: 25000,
    packageCapacity: 30000,
    progress: 0,
    status: 'scheduled',
    aircraftType: 'boeing777',
    aircraftColor: '#6f42c4',
    isSameContinentFlight: false
  },
];

// Helper functions for calculations
const haversineDistance = (lat1, lon1, lat2, lon2) => {
  const R = 6371e3;
  const φ1 = lat1 * Math.PI / 180;
  const φ2 = lat2 * Math.PI / 180;
  const Δφ = (lat2 - lat1) * Math.PI / 180;
  const Δλ = (lon2 - lon1) * Math.PI / 180;

  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
    Math.cos(φ1) * Math.cos(φ2) *
    Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return R * c;
};

const getIntermediatePoint = (lat1, lon1, lat2, lon2, progress) => {
  const φ1 = lat1 * Math.PI / 180;
  const λ1 = lon1 * Math.PI / 180;
  const φ2 = lat2 * Math.PI / 180;
  const λ2 = lon2 * Math.PI / 180;

  const d = haversineDistance(lat1, lon1, lat2, lon2) / 6371e3;
  const a = Math.sin((1 - progress) * d) / Math.sin(d);
  const b = Math.sin(progress * d) / Math.sin(d);

  const x = a * Math.cos(φ1) * Math.cos(λ1) + b * Math.cos(φ2) * Math.cos(λ2);
  const y = a * Math.cos(φ1) * Math.sin(λ1) + b * Math.cos(φ2) * Math.sin(λ2);
  const z = a * Math.sin(φ1) + b * Math.sin(φ2);

  const φ3 = Math.atan2(z, Math.sqrt(x * x + y * y));
  const λ3 = Math.atan2(y, x);

  return [φ3 * 180 / Math.PI, λ3 * 180 / Math.PI];
};

const getBearing = (lat1, lon1, lat2, lon2) => {
  const φ1 = lat1 * Math.PI / 180;
  const φ2 = lat2 * Math.PI / 180;
  const Δλ = (lon2 - lon1) * Math.PI / 180;
  const y = Math.sin(Δλ) * Math.cos(φ2);
  const x = Math.cos(φ1) * Math.sin(φ2) - Math.sin(φ1) * Math.cos(φ2) * Math.cos(Δλ);
  let bearing = Math.atan2(y, x) * 180 / Math.PI;
  if (bearing < 0) bearing += 360;
  return bearing;
};

// Custom airplane icon based on saturation
const createAirplaneIcon = (type, color, rotation = 0) => {
  const iconSvg = {
    'boeing737': `<svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg"><ellipse cx="10" cy="10" rx="1.5" ry="8" fill="${color}" stroke="#ffffff" stroke-width="0.5"/><ellipse cx="10" cy="8" rx="7" ry="1.2" fill="${color}" stroke="#ffffff" stroke-width="0.5"/><ellipse cx="10" cy="14" rx="3" ry="0.8" fill="${color}" stroke="#ffffff" stroke-width="0.5"/><path d="M10 16 L10 18 L9.5 18 L9.5 16 Z" fill="${color}" stroke="#ffffff" stroke-width="0.3"/></svg>`,
    'airbus320': `<svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg"><ellipse cx="10" cy="10" rx="1.8" ry="9" fill="${color}" stroke="#ffffff" stroke-width="0.5"/><ellipse cx="10" cy="7.5" rx="8" ry="1.5" fill="${color}" stroke="#ffffff" stroke-width="0.5"/><ellipse cx="10" cy="14.5" rx="3.5" ry="1" fill="${color}" stroke="#ffffff" stroke-width="0.5"/><path d="M10 16.5 L10 18.5 L9.2 18.5 L9.2 16.5 Z" fill="${color}" stroke="#ffffff" stroke-width="0.3"/></svg>`,
    'boeing777': `<svg width="22" height="22" viewBox="0 0 22 22" fill="none" xmlns="http://www.w3.org/2000/svg"><ellipse cx="11" cy="11" rx="2" ry="10" fill="${color}" stroke="#ffffff" stroke-width="0.5"/><ellipse cx="11" cy="8" rx="9" ry="1.8" fill="${color}" stroke="#ffffff" stroke-width="0.5"/><ellipse cx="11" cy="15" rx="4" ry="1.2" fill="${color}" stroke="#ffffff" stroke-width="0.5"/><path d="M11 17 L11 19.5 L10 19.5 L10 17 Z" fill="${color}" stroke="#ffffff" stroke-width="0.3"/></svg>`,
    'cargo': `<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><ellipse cx="12" cy="12" rx="2.5" ry="10" fill="${color}" stroke="#ffffff" stroke-width="0.6"/><ellipse cx="12" cy="9" rx="10" ry="2" fill="${color}" stroke="#ffffff" stroke-width="0.6"/><ellipse cx="12" cy="16" rx="4.5" ry="1.3" fill="${color}" stroke="#ffffff" stroke-width="0.6"/><path d="M12 18 L12 21 L11 21 L11 18 Z" fill="${color}" stroke="#ffffff" stroke-width="0.4"/></svg>`
  };
  return L.divIcon({
    html: `<div style="transform: rotate(${rotation}deg); display: flex; align-items: center; justify-content: center; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.2));">${iconSvg[type]}</div>`,
    className: 'airplane-icon',
    iconSize: type === 'cargo' ? [24, 24] : type === 'boeing777' ? [22, 22] : [20, 20],
    iconAnchor: type === 'cargo' ? [12, 12] : type === 'boeing777' ? [11, 11] : [10, 10],
    popupAnchor: [0, -12]
  });
};

// Custom airport icon
const createAirportIcon = (isSede = false, saturation = 0) => {
  let size, color, borderColor, borderWidth, shadow;
  if (isSede) {
    size = 32;
    color = '#dc3545';
    borderColor = '#FFD700';
    borderWidth = 4;
    shadow = '0 4px 16px rgba(220, 53, 69, 0.6)';
  } else {
    size = 22;
    borderColor = '#ffffff';
    borderWidth = 3;
    shadow = '0 3px 10px rgba(0,0,0,0.4)';
    if (saturation >= 80) {
      color = '#dc3545';
    } else if (saturation >= 50) {
      color = '#ffc107';
    } else {
      color = '#28a745';
    }
  }
  return new L.DivIcon({
    className: 'airport-marker',
    html: `<div style="background: ${color}; border: ${borderWidth}px solid ${borderColor}; border-radius: 50%; width: ${size}px; height: ${size}px; display: flex; align-items: center; justify-content: center; box-shadow: ${shadow}; position: relative; cursor: pointer; transition: all 0.3s ease;"><i class="fas fa-${isSede ? 'building' : 'plane'}" style="color: white; font-size: ${size * 0.4}px; ${isSede ? '' : 'transform: rotate(45deg);'} text-shadow: 0 1px 3px rgba(0,0,0,0.5); font-weight: bold;"></i>${isSede ? `<div style="position: absolute; top: -6px; right: -6px; background: #FFD700; border: 2px solid white; border-radius: 50%; width: 12px; height: 12px; display: flex; align-items: center; justify-content: center; box-shadow: 0 2px 6px rgba(0,0,0,0.3);"><i class="fas fa-star" style="color: white; font-size: 6px;"></i></div>` : ''}${!isSede && saturation >= 80 ? `<div style="position: absolute; top: -4px; right: -4px; background: #FF0000; border: 1px solid white; border-radius: 50%; width: 8px; height: 8px; animation: alertBlink 1s infinite;"></div>` : ''}</div>`,
    iconSize: [size, size],
    iconAnchor: [size/2, size/2],
    popupAnchor: [0, -size/2]
  });
};

// Component to update markers dynamically
function DynamicMarkers({ flights, airports, activeView }) {
  const map = useMap();
  const markersRef = useRef([]);
  const airportMarkers = useRef(new Map());
  const flightMarkers = useRef(new Map());

  useEffect(() => {
    airportMarkers.current.forEach(marker => map.removeLayer(marker));
    flightMarkers.current.forEach(marker => map.removeLayer(marker));
    airportMarkers.current.clear();
    flightMarkers.current.clear();

    if (activeView === 'airports' || activeView === 'flights') {
      airports.forEach(airport => {
        const isUnlimited = airport.capacity === 'ILIMITADO';
        const saturation = isUnlimited ? 0 : (airport.packages / airport.capacity) * 100;
        const icon = createAirportIcon(airport.isSede, saturation);
        const marker = L.marker([airport.lat, airport.lng], { icon })
          .bindPopup(`
            <div style="font-family: 'Segoe UI', sans-serif; min-width: 320px; background: white; color: #333; border-radius: 12px; padding: 20px; border: none; box-shadow: 0 8px 32px rgba(0,0,0,0.15);">
              <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 15px;">
                <strong style="color: ${airport.isSede ? '#dc3545' : '#007bff'}; font-size: 18px; font-weight: 700;">${airport.name}</strong>
                ${airport.isSede ? `<div style="background: #dc3545; color: white; padding: 4px 12px; border-radius: 20px; font-size: 11px; font-weight: bold; text-transform: uppercase; letter-spacing: 0.5px; box-shadow: 0 2px 8px rgba(220, 53, 69, 0.3);">🏢 SEDE PRINCIPAL</div>` : ''}
              </div>
              <div style="background: #f8f9fa; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; font-size: 13px;">
                  <div><div style="color: #6c757d; font-weight: 600; margin-bottom: 4px;">Código IATA</div><div style="color: #333; font-weight: bold;">${airport.code}</div></div>
                  <div><div style="color: #6c757d; font-weight: 600; margin-bottom: 4px;">País</div><div style="color: #333; font-weight: bold;">${airport.country}</div></div>
                  <div><div style="color: #6c757d; font-weight: 600; margin-bottom: 4px;">Capacidad</div><div style="color: #333; font-weight: bold;">${isUnlimited ? 'ILIMITADA' : airport.capacity.toLocaleString()}</div></div>
                  <div><div style="color: #6c757d; font-weight: 600; margin-bottom: 4px;">Paquetes</div><div style="color: #333; font-weight: bold;">${airport.packages.toLocaleString()}</div></div>
                </div>
              </div>
              ${!isUnlimited ? `<div style="background: white; border: 2px solid #e9ecef; border-radius: 8px; padding: 15px;"><div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;"><span style="color: #495057; font-weight: 600;">Saturación</span><span style="color: ${saturation >= 80 ? '#dc3545' : saturation >= 50 ? '#ffc107' : '#28a745'}; font-weight: bold; font-size: 16px;">${saturation.toFixed(1)}%</span></div><div style="background: #e9ecef; height: 8px; border-radius: 4px; overflow: hidden;"><div style="background: ${saturation >= 80 ? '#dc3545' : saturation >= 50 ? '#ffc107' : '#28a745'}; height: 100%; width: ${Math.min(saturation, 100)}%; border-radius: 4px; transition: width 0.3s ease;"></div></div></div>` : `<div style="background: linear-gradient(135deg, #dc3545, #c82333); color: white; padding: 15px; border-radius: 8px; text-align: center;"><div style="font-weight: bold; font-size: 16px; margin-bottom: 5px;">🏢 SEDE PRINCIPAL</div><div style="font-size: 12px; opacity: 0.9;">Capacidad ilimitada de almacenamiento</div></div>`}
            </div>
          `);
        marker.addTo(map);
        airportMarkers.current.set(airport.code, marker);
      });
    }

    if (activeView === 'flights' && flights.length > 0) {
      flights.forEach(flight => {
        if (flight.progress > 0.01 && flight.progress < 0.99) {
          const icon = createAirplaneIcon(flight.aircraftType, flight.aircraftColor, flight.rotation);
          const loadPercentage = (flight.currentPackages / flight.packageCapacity) * 100;
          const flightDuration = flight.isSameContinentFlight ? '0.5 días (12 horas)' : '1 día (24 horas)';
          const isIntercontinental = !flight.isSameContinentFlight;
          const marker = L.marker([flight.currentLat, flight.currentLng], { icon })
            .bindPopup(`
              <div style="font-family: 'Segoe UI', sans-serif; min-width: 320px; background: white; color: #333; border-radius: 12px; padding: 20px; border: none; box-shadow: 0 8px 32px rgba(0,0,0,0.15);">
                <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 15px;"><div style="display: flex; align-items: center; gap: 10px;"><div style="background: linear-gradient(45deg, #007bff, #0056b3); color: white; padding: 6px 12px; border-radius: 20px; font-weight: bold; font-size: 14px;">✈️ ${flight.id}</div><div style="background: ${isIntercontinental ? '#dc3545' : '#28a745'}; color: white; padding: 3px 8px; border-radius: 12px; font-size: 10px; font-weight: bold; text-transform: uppercase;">${isIntercontinental ? 'INTERCONTINENTAL' : 'INTRACONTINENTAL'}</div></div></div>
                <div style="background: #f8f9fa; padding: 15px; border-radius: 8px; margin-bottom: 15px;"><div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px; font-size: 13px;"><div><div style="color: #6c757d; font-weight: 600; margin-bottom: 6px;">🛫 Origen</div><div style="color: #333; font-weight: 600; font-size: 14px;">${flight.origin.name}</div><div style="color: #666; font-size: 12px; margin-top: 2px;">${flight.origin.code} - ${flight.origin.country}</div></div><div><div style="color: #6c757d; font-weight: 600; margin-bottom: 6px;">🛬 Destino</div><div style="color: #333; font-weight: 600; font-size: 14px;">${flight.destination.name}</div><div style="color: #666; font-size: 12px; margin-top: 2px;">${flight.destination.code} - ${flight.destination.country}</div></div></div></div>
                <div style="background: white; border: 2px solid #e9ecef; border-radius: 8px; padding: 15px; margin-bottom: 15px;"><div style="color: #495057; font-weight: 600; font-size: 14px; margin-bottom: 12px;">📊 Progreso del Vuelo</div><div style="background: #e9ecef; height: 8px; border-radius: 4px; overflow: hidden; margin-bottom: 8px;"><div style="background: linear-gradient(90deg, #007bff, #0056b3); height: 100%; width: ${Math.min(flight.progress * 100, 100)}%; border-radius: 4px; transition: width 0.3s ease;"></div></div><div style="display: flex; justify-content: space-between; font-size: 12px; color: #6c757d; margin-bottom: 12px;"><span><strong>${(flight.progress * 100).toFixed(1)}%</strong> completado</span><span>Duración estimada: <strong>${flightDuration}</strong></span></div></div>
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px; margin-bottom: 15px;"><div style="background: #f1f3f4; padding: 12px; border-radius: 8px; text-align: center;"><div style="color: #495057; font-size: 11px; font-weight: 600; text-transform: uppercase; margin-bottom: 4px;">Altitud</div><div style="color: #007bff; font-size: 16px; font-weight: bold;">${Math.round(flight.altitude).toLocaleString()}</div><div style="color: #6c757d; font-size: 10px;">pies</div></div><div style="background: #f1f3f4; padding: 12px; border-radius: 8px; text-align: center;"><div style="color: #495057; font-size: 11px; font-weight: 600; text-transform: uppercase; margin-bottom: 4px;">Velocidad</div><div style="color: #28a745; font-size: 16px; font-weight: bold;">${Math.round(flight.speed)}</div><div style="color: #6c757d; font-size: 10px;">nudos</div></div></div>
                <div style="background: white; border: 2px solid #e9ecef; border-radius: 8px; padding: 15px;"><div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px;"><span style="color: #495057; font-weight: 600; font-size: 14px;">📦 Capacidad de Carga</span><span style="color: ${loadPercentage >= 80 ? '#dc3545' : loadPercentage >= 50 ? '#ffc107' : '#28a745'}; font-weight: bold; font-size: 16px;">${loadPercentage.toFixed(1)}%</span></div><div style="background: #e9ecef; height: 10px; border-radius: 5px; overflow: hidden; margin-bottom: 10px;"><div style="background: ${loadPercentage >= 80 ? '#dc3545' : loadPercentage >= 50 ? '#ffc107' : '#28a745'}; height: 100%; width: ${Math.min(loadPercentage, 100)}%; border-radius: 5px; transition: width 0.3s ease;"></div></div><div style="display: flex; justify-content: space-between; align-items: center;"><div style="font-size: 12px; color: #6c757d;"><strong>${flight.currentPackages}</strong> / <strong>${flight.packageCapacity}</strong> paquetes</div><div style="background: #007bff; color: white; padding: 3px 8px; border-radius: 12px; font-size: 10px; font-weight: bold;">${flight.aircraftName}</div></div></div>
                <div style="margin-top: 15px; padding: 10px; background: linear-gradient(135deg, #f8f9fa, #e9ecef); border-radius: 8px; text-align: center;"><div style="color: #495057; font-size: 11px; font-weight: 600; margin-bottom: 4px;">ESTADO ACTUAL</div><div style="color: #007bff; font-size: 14px; font-weight: bold; text-transform: uppercase;">${flight.status === 'active' ? '🟢 EN VUELO' : flight.status.toUpperCase()}</div></div>
              </div>
            `);
          marker.addTo(map);
          flightMarkers.current.set(flight.id, marker);
        }
      });
    }

    return () => {
      // Cleanup is handled by the maps above
    };
  }, [flights, airports, activeView, map]);

  return null;
}

const Simulador = () => {
  const [activeView, setActiveView] = useState('airports');
  const [flights, setFlights] = useState(initialFlights);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [totalFlights, setTotalFlights] = useState(initialFlights.length);

  // **CORRECCIÓN:** Ahora usamos useState para los aeropuertos para que sus paquetes puedan ser actualizados.
  const [airports, setAirports] = useState(
    ALL_AIRPORTS.map(airport => ({
      ...airport,
      packages: 0, // Inicializamos paquetes en 0
    }))
  );

  // Funciones memoizadas para los cálculos de la simulación
  const totalPackages = useMemo(() => {
    return flights.reduce((sum, flight) => sum + flight.currentPackages, 0) +
      airports.reduce((sum, airport) => sum + airport.packages, 0);
  }, [flights, airports]);

  const flightsInProgress = useMemo(() => {
    return flights.filter(flight => flight.status === 'active' || flight.status === 'on_route').length;
  }, [flights]);

  const getMostSaturatedAirport = useMemo(() => {
    // Encuentra el aeropuerto más saturado excluyendo la sede
    const regularAirports = airports.filter(a => !a.isSede);
    if (regularAirports.length === 0) return null;
    return regularAirports.reduce((max, airport) => {
      const currentSaturation = (airport.packages / airport.capacity) * 100;
      const maxSaturation = (max.packages / max.capacity) * 100;
      return currentSaturation > maxSaturation ? airport : max;
    });
  }, [airports]);

  // **CORRECCIÓN:** Usamos useEffect para actualizar los datos de los aeropuertos
  useEffect(() => {
    const updateAirports = () => {
      setAirports(prevAirports => {
        const newAirports = prevAirports.map(a => ({ ...a, packages: a.packages }));

        const updatedFlights = flights.map(flight => {
          if (flight.status === 'arrived') {
            const destinationAirport = newAirports.find(a => a.code === flight.destination.code);
            if (destinationAirport) {
              destinationAirport.packages += flight.currentPackages;
            }
            return { ...flight, status: 'completed' };
          }
          return flight;
        });

        // Este setFlights está aquí para desencadenar una re-renderización con los estados actualizados
        setFlights(updatedFlights);
        return newAirports;
      });
    };
    updateAirports();
  }, [flights]);


  // El simulador principal
  useEffect(() => {
    const interval = setInterval(() => {
      setElapsedTime(prevTime => prevTime + 1);

      const newFlights = flights.map(flight => {
        if (flight.status === 'active') {
          const newProgress = flight.progress + 0.01;
          const [newLat, newLng] = getIntermediatePoint(
            flight.origin.lat, flight.origin.lng,
            flight.destination.lat, flight.destination.lng,
            newProgress
          );

          const newRotation = getBearing(flight.currentLat, flight.currentLng, newLat, newLng);

          if (newProgress >= 1) {
            return {
              ...flight,
              progress: 1,
              currentLat: flight.destination.lat,
              currentLng: flight.destination.lng,
              status: 'arrived',
              rotation: newRotation,
              currentPackages: flight.currentPackages,
            };
          }

          return {
            ...flight,
            progress: newProgress,
            currentLat: newLat,
            currentLng: newLng,
            rotation: newRotation,
          };
        }
        return flight;
      });

      // Lógica para asignar nuevos vuelos
      let shouldCreateNewFlight = false;
      if (Math.random() < 0.2) { // 20% de probabilidad por segundo
        shouldCreateNewFlight = true;
      }

      if (shouldCreateNewFlight) {
        const originAirport = ALL_AIRPORTS[Math.floor(Math.random() * ALL_AIRPORTS.length)];
        let destinationAirport = ALL_AIRPORTS[Math.floor(Math.random() * ALL_AIRPORTS.length)];
        while (destinationAirport.id === originAirport.id) {
          destinationAirport = ALL_AIRPORTS[Math.floor(Math.random() * ALL_AIRPORTS.length)];
        }

        const isSameContinent = originAirport.region === destinationAirport.region;
        const newFlightId = `V-${(totalFlights + 1).toString().padStart(3, '0')}`;
        const newPackages = Math.floor(Math.random() * 20000) + 5000;

        const newFlight = {
          id: newFlightId,
          origin: originAirport,
          destination: destinationAirport,
          currentPackages: newPackages,
          packageCapacity: newPackages,
          progress: 0,
          status: 'active',
          aircraftType: 'boeing737', // Asumir un tipo de avión por defecto
          aircraftColor: '#007bff',
          isSameContinentFlight: isSameContinent,
          currentLat: originAirport.lat,
          currentLng: originAirport.lng,
        };

        // **CORRECCIÓN:** El aeropuerto de origen ahora tiene que descargar los paquetes para el vuelo
        setAirports(prevAirports => {
            return prevAirports.map(airport => {
                if(airport.code === originAirport.code){
                    return {...airport, packages: Math.max(0, airport.packages - newPackages)};
                }
                return airport;
            });
        });

        newFlights.push(newFlight);
        setTotalFlights(prev => prev + 1);
      }

      setFlights(newFlights);
    }, 1000); // Se ejecuta cada 1 segundo

    return () => clearInterval(interval);
  }, [flights, totalFlights]);


  const getSaturationColor = useCallback((saturation) => {
    if (saturation >= 80) return '#dc3545';
    if (saturation >= 50) return '#ffc107';
    return '#28a745';
  }, []);

  const getAirportColor = useCallback((code) => {
    const airport = airports.find(a => a.code === code);
    if (!airport) return '#333';
    if (airport.isSede) return '#dc3545';
    const saturation = (airport.packages / airport.capacity) * 100;
    return getSaturationColor(saturation);
  }, [airports, getSaturationColor]);

  // Secciones del UI
  const renderAirportStats = () => {
    return (
      <div className="airport-stats">
        {airports.map(airport => {
          const saturation = airport.capacity === 'ILIMITADO' ? 0 : (airport.packages / airport.capacity) * 100;
          return (
            <div key={airport.id} className="airport-card">
              <div className="card-header">
                <i className="fas fa-plane-arrival"></i>
                <div className="airport-info">
                  <div className="airport-name">{airport.name}</div>
                  <div className="airport-code">{airport.code}</div>
                </div>
              </div>
              <div className="card-body">
                <div className="stat-item">
                  <span>Paquetes:</span>
                  <span className="stat-value">{airport.packages.toLocaleString()}</span>
                </div>
                {!airport.isSede && (
                  <>
                    <div className="stat-item">
                      <span>Capacidad:</span>
                      <span className="stat-value">{airport.capacity.toLocaleString()}</span>
                    </div>
                    <div className="stat-item">
                      <span>Saturación:</span>
                      <span className="stat-value" style={{ color: getSaturationColor(saturation) }}>{saturation.toFixed(1)}%</span>
                    </div>
                    <div className="progress-bar-container">
                      <div className="progress-bar" style={{ width: `${Math.min(saturation, 100)}%`, background: getSaturationColor(saturation) }}></div>
                    </div>
                  </>
                )}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderFlightStats = () => {
    return (
      <div className="flight-stats">
        {flights.filter(f => f.status === 'active').map(flight => {
          const loadPercentage = (flight.currentPackages / flight.packageCapacity) * 100;
          return (
            <div key={flight.id} className="flight-card">
              <div className="card-header">
                <i className="fas fa-plane"></i>
                <div className="flight-info">
                  <div className="flight-id">Vuelo {flight.id}</div>
                  <div className="flight-route">{flight.origin.code} → {flight.destination.code}</div>
                </div>
              </div>
              <div className="card-body">
                <div className="stat-item">
                  <span>Progreso:</span>
                  <span className="stat-value">{Math.floor(flight.progress * 100)}%</span>
                </div>
                <div className="progress-bar-container">
                  <div className="progress-bar" style={{ width: `${Math.floor(flight.progress * 100)}%`, background: '#007bff' }}></div>
                </div>
                <div className="stat-item">
                  <span>Carga:</span>
                  <span className="stat-value" style={{ color: getSaturationColor(loadPercentage) }}>{loadPercentage.toFixed(1)}%</span>
                </div>
                <div className="stat-item">
                  <span>Paquetes:</span>
                  <span className="stat-value">{flight.currentPackages.toLocaleString()}</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="main-container">
      <div className="sidebar">
        <div className="logo-container">
          <i className="fas fa-dove"></i>
          <h1>MoraPack</h1>
          <p>Global Tracking & Logistics</p>
        </div>

        <div className="controls-panel">
          <div className="control-group">
            <h4 className="control-title">Modo de Visualización</h4>
            <div className="toggle-switch">
              <button
                className={`toggle-btn ${activeView === 'airports' ? 'active' : ''}`}
                onClick={() => setActiveView('airports')}
              >
                Aeropuertos
              </button>
              <button
                className={`toggle-btn ${activeView === 'flights' ? 'active' : ''}`}
                onClick={() => setActiveView('flights')}
              >
                Vuelos
              </button>
            </div>
          </div>

          <div className="control-group">
            <h4 className="control-title">Estadísticas Clave</h4>
            <div className="stats-box">
              <div className="stat-item">
                <i className="fas fa-box"></i>
                <div className="stat-info">
                  <div className="stat-label">Paquetes Totales</div>
                  <div className="stat-value">{totalPackages.toLocaleString()}</div>
                </div>
              </div>
              <div className="stat-item">
                <i className="fas fa-plane-departure"></i>
                <div className="stat-info">
                  <div className="stat-label">Vuelos Activos</div>
                  <div className="stat-value">{flightsInProgress}</div>
                </div>
              </div>
              <div className="stat-item">
                <i className="fas fa-clock"></i>
                <div className="stat-info">
                  <div className="stat-label">Tiempo Transcurrido</div>
                  <div className="stat-value">{elapsedTime}s</div>
                </div>
              </div>
            </div>
          </div>

          <div className="control-group">
            <h4 className="control-title">Monitoreo de Aeropuertos</h4>
            <div className="stats-box">
              <div className="stat-item">
                <i className="fas fa-warehouse"></i>
                <div className="stat-info">
                  <div className="stat-label">Paquetes en Sede Principal</div>
                  <div className="stat-value">{airports.find(a => a.isSede)?.packages.toLocaleString() || 0}</div>
                  <div className="stat-sublabel">GRU - Cap. Ilimitada</div>
                </div>
              </div>
              <div className="stat-item">
                <i className="fas fa-exclamation-triangle"></i>
                <div className="stat-info">
                  <div className="stat-label">Aeropuerto Más Saturado</div>
                  <div className="stat-value" style={{ color: getSaturationColor(((getMostSaturatedAirport?.packages || 0) / (getMostSaturatedAirport?.capacity || 1)) * 100) }}>
                    {getMostSaturatedAirport ? (getMostSaturatedAirport.packages / getMostSaturatedAirport.capacity * 100).toFixed(1) + '%' : 'N/A'}
                  </div>
                  <div className="stat-sublabel">{getMostSaturatedAirport?.code || 'N/A'}</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="map-content">
        <MapContainer
          center={[-12.0464, -77.0428]}
          zoom={4}
          minZoom={2}
          maxZoom={10}
          className="map-container"
          worldCopyJump={true}
          maxBounds={[[-90, -180], [90, 180]]}
          maxBoundsViscosity={1.0}
        >
          <TileLayer
            url="https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png"
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
          />
          <DynamicMarkers flights={flights} airports={airports} activeView={activeView} />
        </MapContainer>
      </div>
    </div>
  );
};

export default Simulador;
